def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    op_def = sum(1 for a in op if a == 'D')
    last_op = op[-1]
    last_me = my[-1]

    if op_def == 0:
        return 'C'

    if op_def == 1:
        if last_op == 'D':
            return 'D'
        return 'C'

    dd_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_streak += 1
        else:
            break

    if last_op == 'D' and last_me == 'D' and dd_streak >= 3:
        already_forgiven = False
        for i in range(1, n):
            if my[i] == 'C' and my[i - 1] == 'D' and op[i - 1] == 'D':
                already_forgiven = True
                break
        if not already_forgiven:
            return 'C'

    if last_op == 'D':
        return 'D'
    else:
        return 'C'
